    final wizardLine = output
        .split('\n')
        .reversed
        .firstWhere((l) => l.contains('could not save $slot'));
    for (final line in [keySetLine, wizardLine]) {
      expect(
        line,
        contains('could not save $slot to fake store: the write failed'),
