      'slot is "$canonical"'
      '${twin ? ' — a same-endpoint entry already uses "$canonical"' : ' — move the value with /key set $canonical <value>'}'
      '; then /key delete $stored (the pinned slot keeps winning '
      'while it holds a value)',
