      );
      expect(line, contains('error: 401'));
      expect(line, contains('secure store is not writable'));
      expect(line, contains('/key set FA_KEY_API_KIMI_COM <value>'));
      expect(line, isNot(contains('sk-seed-value')));
    });
  });
}

